/** Beam z range: the beams run from z=5 to z=28 (outside the eaves). */
export const BEAM_Z = [5, 28];
/** House shell footprint: x 10..31, z 8..25 (walls on the perimeter). */
export const HOUSE = { x0: 10, x1: 31, z0: 8, z1: 25 };
/** Atrium (open to the sky): x 17..21, z 12..17; glass ring on x=16, x=22, z=11, z=18. */
export const ATRIUM = { x0: 17, x1: 21, z0: 12, z1: 17 };
/** Entry: front door at x=19, z=9 (the door wall); entry recess z=8. */
export const DOOR = { x: 19, z: 9 };
/** Entrance cell where the walk check starts. */
export const ENTRANCE = [19, 1, 7];
/** Freestanding fireplace and chimney footprint: x 20..21, z 21..22 (y=1..8). */
export const CHIMNEY = { x0: 20, x1: 21, z0: 21, z1: 22 };
/** Conversation pit: x 13..17, z 20..23 (floor y=0, no slab at y=1). */
export const PIT = { x0: 13, x1: 17, z0: 20, z1: 23 };
/** Carport footprint: x 0..9, z 7..21 (deck y=5 on posts at x=1). */
export const CARPORT = { x0: 0, x1: 9, z0: 7, z1: 21, deckY: 5 };
/** Car origin (nose north): x 3..5, z 1..7, y 1..2. */
export const CAR = { x: 3, z: 1 };
/** Palm positions (trunk base): jungle trunk y=1..7 with crown radius 2. */
export const PALMS = [[12, 3], [30, 4], [29, 31]];
/** Mailbox at the head of the driveway. */
export const MAILBOX = { x: 9, z: 1 };
/** Cactus bed (gravel): x 23..29, z 2..4. */
export const CACTUS_BED = { x0: 23, x1: 29, z0: 2, z1: 4 };
/** Kidney pool cells at z (plan.md RESERVED): these are never dirt or deck. */
export const POOL = { 29: [[14, 17], [20, 21]], 30: [[13, 22]], 31: [[13, 22]], 32: [[14, 21]] };
/** True when (x, z) is a kidney pool cell. */
export const inPool = (x, z) => (POOL[z] ?? []).some(([a, b]) => x >= a && x <= b);
/** Room air boxes [x0,y0,z0,x1,y1,z1] (ROOMS in plan.md), keyed by the room name in rooms.json. */
export const ROOM_BOX = {
  gallery: [16, 2, 10, 22, 4, 10],
  kitchen: [11, 2, 9, 15, 4, 13],
  dining: [11, 2, 14, 15, 4, 18],
  living: [11, 2, 19, 21, 4, 24],
  atrium: [17, 1, 12, 21, 4, 17],
  corridor: [23, 2, 9, 24, 4, 21],
  "bedroom 1": [26, 2, 9, 30, 4, 12],
  "bath 1": [26, 2, 14, 27, 4, 16],
  "bath 2": [29, 2, 14, 30, 4, 16],
  "bedroom 2": [26, 2, 18, 30, 4, 20],
  "master bedroom": [23, 2, 22, 30, 4, 24],
};

// ---- seeded randomness -----------------------------------------------------------------------------------------------
/** A seeded rng(seed) returning a function that gives floats in [0, 1) (mulberry32): the same seed gives the same build. */
export function rng(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
// Helpers for the midcentury house, batch h1 (plan.md VOCABULARY). Each takes its position (and facing) as arguments.
// Every write goes through put(): only into air, so a cell an earlier part filled is skipped and reported, never
// overwritten. Nothing here writes ground, sand or floor under its footprint. Each helper returns
// { placed, skipped: [[x, y, z, block]] }. Coordinates are plan.md's absolute ones.
import { B, DIRS, OPPOSITE } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const range = (a, b) => {
  const lo = Math.min(a, b);
  return Array.from({ length: Math.abs(b - a) + 1 }, (_, i) => lo + i);
};
const newOut = () => ({ placed: 0, skipped: [] });
const inBox = (x, z, [x0, x1, z0, z1]) => x >= x0 && x <= x1 && z >= z0 && z <= z1;
const dirName = ([dx, , dz]) => Object.keys(DIRS).find((k) => DIRS[k][0] === dx && DIRS[k][2] === dz);

// the one write path: air only
function put(g, o, x, y, z, [block, state, nbt]) {
  if (!g.isAir(x, y, z)) {
    o.skipped.push([x, y, z, block]);
    return;
  }
  g.set(x, y, z, block, state, nbt);
  o.placed++;
}

// Exterior --------------------------------------------------------------------------------------------------------

/** White stucco fill over the box x0..x1, z0..z1, y0..y1 (plan: y=2..4). */
export function stucco_wall(g, x0, z0, x1, z1, y0 = 2, y1 = 4) {
  const o = newOut();
  for (const x of range(x0, x1)) for (const z of range(z0, z1)) for (const y of range(y0, y1)) {
    put(g, o, x, y, z, ["white_concrete", {}]);
  }
  return o;
}

/**
 * A sliding-door opening, width cells along x from x0 at row z: air at y0..y0+1 (never closed), glass_pane at y0+2.
 * Anything standing in the opening is reported as skipped instead of being removed.
 */
export function slider_gap(g, x0, z, y0 = 2, width = 2) {
  const o = newOut();
  for (const x of range(x0, x0 + width - 1)) {
    for (const y of [y0, y0 + 1]) {
      if (!g.isAir(x, y, z)) o.skipped.push([x, y, z, g.blockAt(x, y, z)]);
    }
    put(g, o, x, y0 + 2, z, B.pane());
  }
  return o;
}

// Plan holes in the roof band: the atrium (x 17..21, z 12..17) and the chimney (x 20..21, z 21..22).
const ATRIUM_HOLE = [17, 21, 12, 17];
const CHIMNEY_HOLE = [20, 21, 21, 22];

/** The eave/ridge slab band over x=9..32 at rows zA..zB, half = "bottom" | "top"; skips the atrium and chimney holes. */
export function roof_band(g, zA, zB, y, half) {
  if (half !== "bottom" && half !== "top") throw new Error(`roof_band: half must be bottom or top, got ${half}`);
  const o = newOut();
  for (const x of range(9, 32)) for (const z of range(zA, zB)) {
    if (inBox(x, z, ATRIUM_HOLE) || inBox(x, z, CHIMNEY_HOLE)) continue;
    put(g, o, x, y, z, B.slab("smooth_stone", half));
  }
  return o;
}

/** Checkerboard breeze screen: white_concrete where (x + y) is even, air elsewhere, over x0..x1, y0..y1 at row z. */
export function breeze_screen(g, x0, x1, y0, y1, z) {
  const o = newOut();
  for (const x of range(x0, x1)) for (const y of range(y0, y1)) {
    if ((x + y) % 2 === 0) put(g, o, x, y, z, ["white_concrete", {}]);
  }
  return o;
}

// jungle_log trunk y=1..7; leaves at y=7 (the 3x3 ring) and y=6 (a radius-2 cross plus the diagonals)
const CROWN_Y6 = [[1, 0], [2, 0], [-1, 0], [-2, 0], [0, 1], [0, 2], [0, -1], [0, -2], [1, 1], [1, -1], [-1, 1], [-1, -1]];

/** A palm at (x, z): trunk y=1..7 and a crown; leaves persistent; cells already filled (e.g. by the roof) are skipped. */
export function palm(g, x, z) {
  const o = newOut();
  const leaves = ["jungle_leaves", { persistent: "true" }];
  for (let y = 1; y <= 7; y++) put(g, o, x, y, z, B.log("jungle", "y"));
# REQUIRED ELEMENTS: mid-century modern house (checklist)

Coordinates are from plan.md (x east, y up, z south; z=0 is the street). "Part" = the part that builds it (see PARTS in
plan.md); "Vocab" = the helper in VOCABULARY. Nothing here is a coloured full block standing in for an object.

## A. Form and structure
- [x] **1. Low, long horizontal house**, 22 x 18, walls y=1..5, roof to y=7. Part 1 shell. Vocab `stucco_wall`, `header_course`.
- [ ] **2. Very low-pitch gable roof, deep eaves**: hand-built stepped slab roof, ridge along x at z=16..17 (y=7), eaves z=6/27 (y=6), 2-cell overhang front and back, 1 at the gable ends; dark_oak_slab fascia ring. Part 3. Vocab `roof_band`, `fascia_ring`.
