export function fascia_ring(g, { x0 = 9, x1 = 32, z0 = 6, z1 = 27, hole = [17, 12, 21, 17], swap = "smooth_stone_slab" } = {}) {
  const t = tally();
  const cells = new Map();
  for (const x of span(x0, x1)) { cells.set(`${x},${z0}`, [x, z0]); cells.set(`${x},${z1}`, [x, z1]); }
